test_suite:
test('startIndex is 0 at scroll 0', () => {
  const { result } = renderHook(() =>
    useVirtualOffset({ itemHeight: 50, containerHeight: 200, itemCount: 100 })
  );
  expect(result.current.startIndex).toBe(0);
});

test('endIndex covers container height', () => {
  const { result } = renderHook(() =>
    useVirtualOffset({ itemHeight: 50, containerHeight: 200, itemCount: 100 })
  );
  expect(result.current.endIndex).toBeGreaterThanOrEqual(4);
});

test('onScroll updates startIndex', () => {
  const { result } = renderHook(() =>
    useVirtualOffset({ itemHeight: 50, containerHeight: 200, itemCount: 100 })
  );
  act(() => result.current.onScroll({ currentTarget: { scrollTop: 150 } } as any));
  expect(result.current.startIndex).toBe(3);
});

test('offsetY equals startIndex * itemHeight', () => {
  const { result } = renderHook(() =>
    useVirtualOffset({ itemHeight: 50, containerHeight: 200, itemCount: 100 })
  );
  act(() => result.current.onScroll({ currentTarget: { scrollTop: 150 } } as any));
  expect(result.current.offsetY).toBe(result.current.startIndex * 50);
});

test('endIndex does not exceed itemCount', () => {
  const { result } = renderHook(() =>
    useVirtualOffset({ itemHeight: 50, containerHeight: 200, itemCount: 5 })
  );
  act(() => result.current.onScroll({ currentTarget: { scrollTop: 100 } } as any));
  expect(result.current.endIndex).toBeLessThanOrEqual(5);
});

// __hidden__
test('startIndex does not go negative', () => {
  const { result } = renderHook(() =>
    useVirtualOffset({ itemHeight: 50, containerHeight: 200, itemCount: 10 })
  );
  act(() => result.current.onScroll({ currentTarget: { scrollTop: -100 } } as any));
  expect(result.current.startIndex).toBeGreaterThanOrEqual(0);
});

solution:
import { useState, useCallback } from 'react';

interface VirtualOffsetOptions {
  itemHeight: number;
  containerHeight: number;
  itemCount: number;
}

export function useVirtualOffset({ itemHeight, containerHeight, itemCount }: VirtualOffsetOptions) {
  const [scrollTop, setScrollTop] = useState(0);

  const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight));
  const visibleCount = Math.ceil(containerHeight / itemHeight);
  const endIndex = Math.min(itemCount, startIndex + visibleCount + 1);
  const offsetY = startIndex * itemHeight;

  const onScroll = useCallback((e: React.UIEvent<HTMLElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  return { startIndex, endIndex, offsetY, onScroll };
}
